}]

// ⑤ SECO · LO QUE SE HABRÍA ESCRITO · CC#1 · 2026-09-29. En modo seco NADA se escribe ni se avisa: ni la tabla, ni Drive, ni la sala.
// Pero llega hasta acá con las MISMAS filas y avisos que el camino real (los arma ④), y aquí se VALIDAN sus formas.
const c = $input.first().json
const f = c.fila_parte || {}
const faltan = []
for (const k of ['client_id', 'title', 'output_type', 'content', 'content_text', 'producing_agent', 'status', 'provenance_tag']) {
  if (f[k] === undefined || f[k] === null || f[k] === '') faltan.push('fila_parte.' + k)
}
if (f.output_type !== 'campaign_brief_pack') faltan.push('fila_parte.output_type debe ser campaign_brief_pack')
if (f.status !== 'draft') faltan.push('fila_parte.status debe ser draft')
const a = c.payload_cable || {}
for (const k of ['event_type', 'worker_id', 'worker_name', 'resultado', 'client_id']) {
  if (a[k] === undefined || a[k] === null || a[k] === '') faltan.push('payload_cable.' + k)
}
if (a.event_type !== 'run_completed') faltan.push('payload_cable.event_type debe ser run_completed')
if (a.worker_name !== 'brief') faltan.push('payload_cable.worker_name debe ser brief')
const habria_cerrado_como = c.parte_valido === false ? 'ERROR · PARTE_NO_VALIDO · ' + c.motivo_invalido : 'parte_terminado'
const salida = {
  json: {
    seco: true,
    escrituras_reales: 0,
    no_se_escribio_en: ['client_historical_outputs', 'Drive (texto-a-drive)', 'la sala (SALA_CALLBACK_URL)'],
    dry_run_enviado_al_nodo_que_paga: c.cuerpo_dry_run_enviado,
    la_vuelta_del_redactor: { llego: c.llego_la_vuelta, real: c.vuelta_real, simulacro: c.simulacro_usado, costo_usd: c.vuelta_costo_usd, modelo: c.vuelta_modelo },
    chequeos: { legible: c.parte_legible, ok: c.chequeos_ok, por_chequeo: c.por_chequeo, entregables: c.entregables, pendientes: c.pendientes_declarados },
    habria_guardado: { tabla: 'client_historical_outputs', output_type: f.output_type, status: f.status, titulo: f.title, largo_del_parte: String(f.content || '').length, provenance_tag_claves: Object.keys(f.provenance_tag || {}) },
    habria_subido_a_drive_con_titulo: f.title,
    parte_valido: c.parte_valido !== false,
    motivo_invalido: c.motivo_invalido || null,
    habria_cerrado_como,
    habria_avisado: a,
    formas_validas: faltan.length === 0,
    faltan,
  },
}
// 🔴 el ensayo ejerce el MISMO veredicto que el camino real: un parte inválido termina la corrida en error (con la salida ya guardada en la ejecución)
if (c.parte_valido === false) throw new Error('PARTE_NO_VALIDO (modo seco) · ' + c.motivo_invalido + ' · en modo real habría subido a Drive con la marca y cerrado en error')
return [salida]

// ⑤ ¿GUARDÓ Y SALIÓ EL PDF? · CC#1 · 2026-09-29. Una corrida sin parte guardado o sin PDF NO puede salir exitosa (regla 12-sep de planeación).
// El guardado va ANTES de Drive a propósito: si Drive falla, el parte NO se pierde.
const v = $('④ Chequeos').first().json
let guardado = false, guardado_id = null
try {
  const g = $('⑤ Guardar el parte').first().json
  const gb = g && g.body ? g.body : g
  const fila = Array.isArray(gb) ? gb[0] : gb
  guardado = !!(fila && fila.id)
  guardado_id = (fila && fila.id) || null
} catch (x) { guardado = false }
let rec = null
try { const d = $('⑤ Parte a Drive').first().json; rec = d && d.body ? d.body : d } catch (x) { rec = null }
const hayPdf = !!(rec && rec.ok === true && rec.file_id)
const problemas = []
if (v.parte_valido === false) problemas.push('PARTE NO VÁLIDO · ' + v.motivo_invalido)
if (!v.llego_la_vuelta) problemas.push('la vuelta del redactor NO llegó')
if (!guardado) problemas.push('el parte NO quedó guardado en client_historical_outputs')
if (!hayPdf) problemas.push('Drive no devolvió un archivo (' + String((rec && rec.motivo) || 'sin motivo') + ')')
return [{
  json: {
    ok: problemas.length === 0,
    parte_guardado: guardado,
    parte_guardado_id: guardado_id,
    hay_pdf: hayPdf,
    file_id: (rec && rec.file_id) || null,
    url: (rec && rec.url) || null,
    chequeos_ok: v.chequeos_ok,
    hallazgos: (v.hallazgos || []).length,
    entregables: v.entregables,
    pendientes_declarados: v.pendientes_declarados,
    problemas,
    parte_valido: v.parte_valido !== false,
    motivo_invalido: v.motivo_invalido || null,
    client_id: v.client_id,
    // la sala se entera del resultado REAL: un parte con problemas no se anuncia como terminado limpio
    payload_cable: { ...v.payload_cable, resultado: problemas.length === 0 ? 'parte_terminado' : (v.parte_valido === false ? 'parte_no_valido' : 'parte_con_problemas'), ...(problemas.length ? { problemas } : {}) },
  },
}]

// ⑥ EL CABLE DE VUELTA NO PUEDE SER MUDO · CC#1 · 2026-09-29 · igual que planeación.
// Si no volvió, la sala NUNCA se entera de que la corrida terminó y su marca queda sin resolver.
const r = $input.first().json || {}
const volvio = r.ok === true
let corr = null
try { corr = $('⓪ Sobre · llave · modo seco').first().json._sala_correlation_id || null } catch (e) { corr = null }
// Falla RUIDOSA solo si la sala lo despachó: un disparo a mano no tiene a quién contestarle.
if (corr && !volvio) {
  throw new Error('CABLE_DE_VUELTA_MUDO · la sala NO se enteró de que la corrida terminó · código ' + String(r.code || r.error || 'sin código'))
}
// 🔴 LA CORRIDA NO CIERRA «CORRECTA» SI EL PARTE NO VALE (encargo Lenovo 30-sep §2): el cable YA declaró el resultado real arriba;
// acá la corrida termina en ERROR visible con el motivo, no en verde. Antes este nodo devolvía siempre `cierre: 'parte_terminado'`.
let cierrePrevio = null
try { cierrePrevio = $('⑤ ¿Guardó y salió el PDF?').first().json } catch (e) { cierrePrevio = null }
if (cierrePrevio && cierrePrevio.ok === false) {
  throw new Error((cierrePrevio.parte_valido === false ? 'PARTE_NO_VALIDO' : 'PARTE_CON_PROBLEMAS') + ' · ' + (cierrePrevio.problemas || []).join(' | ') + ' · la sala ya fue avisada del resultado real')
}
return [{
  json: {
    cierre: 'parte_terminado',
    vuelta_ok: volvio,
    vuelta_detalle: volvio ? r.event_id || 'sin event_id' : r.code || r.detail || r.error || 'sin respuesta de la sala',
    despachado_por_la_sala: !!corr,
  },
}]

// ⓪ EL SOBRE · LA LLAVE · EL MODO SECO · CC#1 · 2026-09-29 · encargo Lenovo §1.
// Este flujo PAGA (un agente). Por eso: (1) exige la llave de despacho del motor (lección E67: un POST con la marca
// copiada arrancaba una corrida paga) y (2) exige `dry_run` EXPLÍCITO (true|false) en el sobre · no se asume nunca
// (lección 28-sep: en otro flujo el dry_run moría en el primer nodo y una prueba «gratis» cobró US$ 0,37).
const w = $input.first().json || {}
const body = w.body && typeof w.body === 'object' ? w.body : {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}

const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) {
  throw new Error('BRIEF_CERRADO · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) en su entorno · este flujo paga y queda cerrado hasta que exista · E67.')
}
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) {
  throw new Error('BRIEF_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · este flujo paga y solo lo despierta la sala · E67.')
}

if (!body.client_id) throw new Error('BRIEF_SIN_CLIENTE · falta client_id en el sobre · se DETIENE y no escribe nada')
// el client_id se pega en direcciones de la base: solo un uuid, nada más
if (!/^[0-9a-fA-F-]{36}$/.test(String(body.client_id))) throw new Error('BRIEF_CLIENTE_INVALIDO · client_id no es un uuid · se DETIENE y no escribe nada')
if (typeof body.dry_run !== 'boolean') {
  throw new Error('BRIEF_DRY_RUN_AUSENTE · el sobre debe traer dry_run explícito (true o false) · no se asume · se DETIENE antes de gastar')
}

