var MENCION = {
  tu: /\b(tutea\w*|tuteo|tutear|tu)\b/g,
  vos: /\b(vos|voseo|vosea\w*|vosear)\b/g,
  usted: /\b(usted|ustedeo|ustedea\w*|trato formal)\b/g,
}
function mencionesDelTexto(texto) {
  var t = sinTildes(texto)
  var out = { tu: 0, vos: 0, usted: 0, negados: [] }
  TRATOS.forEach(function (k) {
    var re = new RegExp(MENCION[k].source, 'g')
    var m
    while ((m = re.exec(t)) !== null) {
      // «tu» a secas es un posesivo muy común («tu puerta»): sólo cuenta si va pegado a una indicación de trato (tú/sabes/pides …) o es tuteo/tutea
      if (m[1] === 'tu' && !/tu\s*[\/·,]\s*(sabes|pides|tienes|quieres|puedes|eres|vienes)/.test(t.slice(m.index, m.index + 30))) continue
      var antes = t.slice(Math.max(0, m.index - 24), m.index)
      if (/\b(nunca|jamas|no|ni|sin|evita|evitar|evites)\s+(\w+\s+){0,2}$/.test(antes)) out.negados.push(k)
      else out[k] += 1
    }
  })
  return out
}

// el trato habitual del país SÓLO cuando nadie lo dijo (baja confianza · se declara) · sin país conocido no hay default
var POR_PAIS = { argentina: 'vos', uruguay: 'vos', paraguay: 'vos', ecuador: 'tu', mexico: 'tu', peru: 'tu', chile: 'tu', espana: 'tu', bolivia: 'tu', venezuela: 'tu', panama: 'tu', 'costa rica': 'usted' }

/**
 * `manual` = { voice_description, writing_style, tone_guidelines } · `ficha` = { config, country, market }
 * → { trato: 'tu'|'vos'|'usted'|'no_definido'|'conflicto', fuente, evidencia }
 */
function resolverTrato(manual, ficha) {
  var m = manual || {}
  var f = ficha || {}
  var tg = m.tone_guidelines && typeof m.tone_guidelines === 'object' ? m.tone_guidelines : {}
  var cfg = f.config && typeof f.config === 'object' ? f.config : {}
  var voz = cfg.voz && typeof cfg.voz === 'object' ? cfg.voz : {}
  var explicitos = [
    ['manual.tone_guidelines.trato', tg.trato], ['manual.tone_guidelines.tratamiento', tg.tratamiento], ['manual.tone_guidelines.address_form', tg.address_form],
    ['ficha.config.voz.trato', voz.trato], ['ficha.config.trato', cfg.trato],
  ]
  for (var i = 0; i < explicitos.length; i++) {
    var v = tratoDeValor(explicitos[i][1])
    if (v) return { trato: v, fuente: explicitos[i][0].indexOf('manual') === 0 ? 'manual' : 'ficha', evidencia: explicitos[i][0] + ' = «' + explicitos[i][1] + '»' }
  }
  var texto = [m.voice_description, m.writing_style, m.tone_guidelines && Object.keys(tg).length ? JSON.stringify(tg) : ''].filter(Boolean).join(' · ')
  if (texto) {
    var me = mencionesDelTexto(texto)
    var pos = TRATOS.filter(function (k) { return me[k] > 0 })
    if (pos.length === 1) return { trato: pos[0], fuente: 'manual', evidencia: 'la descripción de voz del manual lo dice (' + pos[0] + (me.negados.length ? ' · niega ' + me.negados.join(', ') : '') + ')' }
    if (pos.length > 1) return { trato: 'conflicto', fuente: 'manual', evidencia: 'la descripción de voz menciona más de un trato (' + pos.join(' y ') + ') sin negar ninguno · no se puede elegir' }
  }
  var pais = sinTildes(f.country).trim() || sinTildes(String(f.market || '').split(/[·|,;\/]/).pop()).trim()
  if (pais && POR_PAIS[pais]) return { trato: POR_PAIS[pais], fuente: 'default_por_pais', evidencia: 'ni el manual ni la ficha lo dicen: se usa el trato habitual de «' + pais + '» (BAJA confianza · conviene ponerlo en el manual)' }
  return { trato: 'no_definido', fuente: 'ninguna', evidencia: 'ni el manual ni la ficha dicen el trato y no hay país conocido · NO se comprueba' }
}

// ───────────────────────────── las formas ─────────────────────────────
// verbos de uso comercial/llamado a la acción (infinitivos regulares en la conjugación del voseo) · es LENGUA, no clientes
var VERBOS = ('pedir mandar escribir enviar llamar contar avisar venir hacer comprar probar reservar consultar mirar seguir sumar unir descubrir elegir disfrutar compartir ordenar encargar contactar visitar ' +
  'decir tener querer poder saber vivir sentir pasar dejar traer llevar buscar conocer escuchar preguntar responder recibir pagar cambiar usar armar crear ahorrar aprovechar animar inscribir registrar ' +
  'suscribir invitar acompañar agendar cotizar solicitar averiguar entrar ingresar escoger pensar imaginar atreverse quedar poner salir').split(' ')
var CLITICOS = ['', 'lo', 'la', 'los', 'las', 'le', 'les', 'me', 'nos', 'te', 'se']

function radical(inf) { return inf.replace(/se$/, '').slice(0, -2) }
function vocalTematica(inf) { var f = inf.replace(/se$/, ''); return f.slice(-2, -1) === 'a' || /ar$/.test(f) ? 'a' : /er$/.test(f) ? 'e' : 'i' }
var ACENTO = { a: 'á', e: 'é', i: 'í' }

function formasVoseo() {
  var s = {}
  VERBOS.forEach(function (inf) {
    var r = radical(inf), v = vocalTematica(inf)
    s[r + ACENTO[v]] = true // pedí · mandá · escribí
    CLITICOS.slice(1).forEach(function (c) { s[r + v + c] = true }) // pedilo · mandalo · escribinos
    s[r + ACENTO[v] + 's'] = true // pedís · mandás · tenés (voseo presente)
    if (v === 'e') s[r + 'és'] = true
  })
  ;['sos', 'tenés', 'querés', 'podés', 'sabés', 'venís', 'hacés', 'decís', 'ponés', 'salís', 'vení', 'poné', 'hacé', 'decí', 'tené', 'salí'].forEach(function (w) { s[w] = true })
  return s
}
// el tuteo: pronombre, presente 2.ª persona regular y el imperativo con clítico acentuado («pídelo», «mándanos»)
function acentuarUltimaVocal(stem) {
  var i = stem.length - 1
  while (i >= 0 && !/[aeiou]/.test(stem[i])) i--
  if (i < 0) return stem
  return stem.slice(0, i) + ({ a: 'á', e: 'é', i: 'í', o: 'ó', u: 'ú' })[stem[i]] + stem.slice(i + 1)
}
function formasTuteo() {
  var s = {}
  VERBOS.forEach(function (inf) {
    var r = radical(inf), v = vocalTematica(inf)
    s[r + (v === 'a' ? 'as' : 'es')] = true // mandas · escribes · tienes(irregular: ver abajo)
    var imp = r + (v === 'a' ? 'a' : 'e')
    CLITICOS.slice(1).forEach(function (c) { s[acentuarUltimaVocal(imp) + c] = true }) // mándalo · escríbenos
  })
  ;['eres', 'tienes', 'quieres', 'puedes', 'sabes', 'vienes', 'haces', 'dices', 'pides', 'pídelo', 'pídela', 'pídenos', 'ven', 'haz', 'dime', 'cuéntanos', 'escríbenos', 'avísanos', 'llámanos', 'mándanos', 'tú'].forEach(function (w) { s[w] = true })
  return s
}
// formas de usted: pronombre (no «ustedes», que es plural neutro) y el imperativo/presente formal regular
function formasUsted() {
  var s = { usted: true }
  VERBOS.forEach(function (inf) {
    var r = radical(inf), v = vocalTematica(inf)
    s[r + (v === 'a' ? 'e' : 'a')] = true // mande · escriba
    CLITICOS.slice(1).forEach(function (c) { s[acentuarUltimaVocal(r + (v === 'a' ? 'e' : 'a')) + c] = true })
  })
  return s
}
var VOSEO = formasVoseo(), TUTEO = formasTuteo(), USTED = formasUsted()
// palabras que coinciden por casualidad con una forma generada y NO son esa forma (sustantivos y adverbios comunes)
var FALSOS = { mas: 1, pase: 1, deje: 1, cree: 1, vea: 1, sienta: 1, nos: 1 }

/** las palabras (con tilde) de un texto, en minúscula */
function palabras(texto) { return String(texto || '').toLowerCase().match(/[a-záéíóúüñ]+/g) || [] }

/** las formas de cada trato que aparecen en el texto: { vos: [palabras], tu: [...], usted: [...] } */
function formasDeTrato(texto) {
  var out = { vos: [], tu: [], usted: [] }
  var add = function (k, w) { if (out[k].indexOf(w) === -1) out[k].push(w) }
  palabras(texto).forEach(function (w) {
    if (w === 'vos') add('vos', w)
    else if (VOSEO[w]) add('vos', w)
    else if (TUTEO[w]) add('tu', w)
    else if (USTED[w] && !FALSOS[w]) add('usted', w)
  })
  return out
}

/**
 * ¿el texto respeta el trato de la marca? → [{ chequeo, detalle, fatal:false }]
 * `donde` = «la pieza» · «el brief». Sin trato definido (o en conflicto) NO se comprueba y se dice.
 */
function chequearTrato(resolucion, texto, donde) {
  var r = resolucion || { trato: 'no_definido' }
  var d = donde || 'el texto'
  if (r.trato === 'no_definido' || r.trato === 'conflicto') return []
  var formas = formasDeTrato(texto)
  var otros = TRATOS.filter(function (k) { return k !== r.trato })
  var hallados = []
  otros.forEach(function (k) { formas[k].forEach(function (w) { hallados.push({ w: w, k: k }) }) })
  // el usted «mande/llame» coincide con presentes de 3.ª persona: sólo se avisa si el trato de la marca NO es usted y no hay forma más clara
  if (!hallados.length) return []
  var nombre = { tu: 'tuteo', vos: 'voseo', usted: 'usted' }
  return [{
    chequeo: 'trato_distinto_al_del_cliente',
    detalle: d + ' trae formas de otro trato: ' + hallados.slice(0, 6).map(function (x) { return '«' + x.w + '» (' + nombre[x.k] + ')' }).join(' · ') + ' y el trato de la marca es ' + nombre[r.trato] + ' (' + r.fuente + ': ' + r.evidencia + ')',
    fatal: false,
  }]
}

/** el bloque para el pedido/brief: el trato y de dónde sale · y qué hacer si otro texto (el brief) trae otro */
function bloqueDeTrato(resolucion) {
  var r = resolucion || { trato: 'no_definido', fuente: 'ninguna', evidencia: '' }
  var nombre = { tu: 'TÚ (tuteo)', vos: 'VOS (voseo)', usted: 'USTED' }
  if (r.trato === 'no_definido') return 'F) EL TRATO. El sistema NO sabe qué trato (tú · vos · usted) usa esta marca: ni el manual ni la ficha lo dicen. Escribe con el trato que use el manual en sus ejemplos y DECLÁRALO en «no_pude_cumplir» («trato no definido»).'
  if (r.trato === 'conflicto') return 'F) EL TRATO. El manual menciona más de un trato sin elegir (' + r.evidencia + '). No adivines: declara «trato en conflicto» en «no_pude_cumplir» y evita las formas de segunda persona cuando puedas.'
  return ['F) EL TRATO de esta marca es ' + nombre[r.trato] + ' (fuente: ' + r.fuente + ' · ' + r.evidencia + ').',
    '   Todo lo que se lee en la pieza (titular, texto, llamado) va en ese trato, sin mezclar. Si el brief trae formas de OTRO trato (por ejemplo una frase copiada de una conversación), NO las copies:',
    '   conviértelas al trato de la marca y dilo en «que_miro». El manual de marca manda sobre el brief.'].join('\n')
}


// LOS CHEQUEOS DEL PARTE DE TRABAJO · CC#1 · 2026-09-29 · encargo Lenovo §1.2 ④ · arquitectura §4.
// Lógica PURA (sin red, sin `this`, sin `require` fuera de este archivo): se prueba a costo cero y se pega
// tal cual dentro del nodo «④ Chequeos» del flujo `zero-risk/brief` (el constructor la antepone al nodo).
//
// REGLA DE LA CASA: lo que falle SE DECLARA en el parte · NO se corrige solo · NO se rellena.
// Por qué en código y no con un juez de pago: los chequeos que importan son CONTABLES y cazan lo que un
// agente pago no ve (medido: el manual prohibía «ghost kitchen», la usaba 3 veces y el juez lo aprobó 0,94).

var CAMPOS_OBLIGATORIOS = [
  'id', 'plataforma', 'tipo_de_pieza', 'que_es', 'de_que_parte_del_plan', 'objetivo', 'segmento', 'protagonista',
  'mensaje', 'hipotesis', 'limites', 'sintaxis', 'llamado_a_la_accion', 'variantes', 'aprueba_y_para_cuando',
]
var CAMPOS_LISTA = ['vocabulario_obligatorio', 'prohibido', 'negativos']
var TIPOS_SIN_VIDEO = ['imagen', 'texto', 'listado', 'configuracion', 'carrusel', 'documento', 'otro']
var TIPOS_QUE_NO_SE_BRIEFEAN = ['video', 'audio', 'reel']
var CENTINELA = /\d+[.,]77(?!\d)/

/** minúsculas, sin tildes, sin signos, espacios simples · para comparar textos. */
function normalizar(s) {
  return String(s === null || s === undefined ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9ñ ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

/** Todos los textos de un valor (string, array, objeto) en una sola cadena. */
function aTexto(v) {
  if (v === null || v === undefined) return ''
  if (typeof v === 'string') return v
  if (Array.isArray(v)) return v.map(aTexto).join(' \n ')
  if (typeof v === 'object') return Object.keys(v).map(function (k) { return aTexto(v[k]) }).join(' \n ')
  return String(v)
}

/**
 * LECTOR TOLERANTE DE COMILLAS · CC#1 · 2026-10-01 · GO de Emilio. El redactor a veces escribe comillas dobles SIN ESCAPAR dentro de un texto del JSON
 * («... el mensaje "Hola, quiero hacer un pedido"» · pasó en las DOS corridas reales del 29 y el 30-sep) y eso invalidaba un parte completo.
 * Una comilla dentro de un texto sólo lo CIERRA si lo que sigue es estructura JSON (`:` `}` `]` o una coma seguida de `"` `{` `[` `}` `]`); si no, es parte del texto y se escapa.
 * Es una reparación de FORMATO, nunca de contenido: sólo se acepta si el resultado parsea Y trae la lista «entregables» · se DECLARA (reparado:true + cuántas) · lo que no parsea sigue siendo ilegible.
 */
function repararComillas(s) {
  var out = ''
  var dentro = false
  var reparadas = 0
  for (var i = 0; i < s.length; i++) {
    var ch = s[i]
    if (!dentro) { out += ch; if (ch === '"') dentro = true; continue }
    if (ch === '\\') { out += ch + (s[i + 1] === undefined ? '' : s[i + 1]); i++; continue }
    if (ch !== '"') { out += ch; continue }
    var j = i + 1
    while (j < s.length && /\s/.test(s[j])) j++
    var sig = s[j]
    var cierra = sig === ':' || sig === '}' || sig === ']' || sig === undefined
    if (sig === ',') {
      var k = j + 1
      while (k < s.length && /\s/.test(s[k])) k++
      cierra = s[k] === '"' || s[k] === '{' || s[k] === '[' || s[k] === '}' || s[k] === ']'
    }
    if (cierra) { out += ch; dentro = false } else { out += '\\"'; reparadas++ }
  }
  return { texto: out, reparadas: reparadas }
}

/** Saca el JSON del texto del redactor (bloque ```json o el primer objeto completo). */
function extraerParte(texto) {
  var t = String(texto || '')
  if (!t.trim()) return { legible: false, motivo: 'el redactor devolvió texto vacío' }
  var candidatos = []
  var abre = t.indexOf('```json')
  if (abre !== -1) {
    var ini = t.indexOf('\n', abre)
    var fin = t.indexOf('```', ini + 1)
    if (ini !== -1 && fin !== -1) candidatos.push(t.slice(ini + 1, fin))
  }
  var a = t.indexOf('{')
  var b = t.lastIndexOf('}')
  if (a !== -1 && b > a) candidatos.push(t.slice(a, b + 1))
  for (var i = 0; i < candidatos.length; i++) {
    try {
      var j = JSON.parse(candidatos[i])
      var p = j && j.parte ? j.parte : j
      if (p && Array.isArray(p.entregables)) return { legible: true, parte: p }
    } catch (e) { /* se prueba la reparación de comillas y luego el siguiente candidato */ }
    try {
      var rep = repararComillas(candidatos[i])
      if (rep.reparadas > 0) {
        var j2 = JSON.parse(rep.texto)
        var p2 = j2 && j2.parte ? j2.parte : j2
        if (p2 && Array.isArray(p2.entregables)) return { legible: true, parte: p2, reparado: true, comillas_reparadas: rep.reparadas }
      }
    } catch (e2) { /* sigue ilegible */ }
  }
  return { legible: false, motivo: 'no hay un JSON con la lista «entregables» en la respuesta del redactor' }
}

function palabraPresente(textoNorm, palabra) {
  var p = normalizar(palabra)
  if (!p) return false
  return (' ' + textoNorm + ' ').indexOf(' ' + p + ' ') !== -1
}

/**
 * Corre TODOS los chequeos. `manual.forbidden_words` = lista de palabras prohibidas del manual (array de strings).
 * `planTexto` = texto del plan vigente (para verificar que la cita a su parte existe).
 * Devuelve {ok, hallazgos[], por_chequeo{}, entregables_revisados}. NO modifica nada.
 */
function chequear(parte, manual, planTexto) {
  var hallazgos = []
  var falla = function (chequeo, entregable, detalle) { hallazgos.push({ chequeo: chequeo, entregable: entregable || null, detalle: detalle }) }
  var ents = parte && Array.isArray(parte.entregables) ? parte.entregables : []
  if (!ents.length) falla('sin_entregables', null, 'la lista de entregables está vacía · un parte sin entregables no es un parte')
  var prohibidas = (manual && Array.isArray(manual.forbidden_words) ? manual.forbidden_words : []).filter(Boolean)
  var planNorm = normalizar(planTexto)

  var ids = {}
  var mensajes = {}
  for (var i = 0; i < ents.length; i++) {
    var e = ents[i] || {}
    var idE = e.id ? String(e.id) : '(sin id · posición ' + (i + 1) + ')'

    // ── identificador + trazabilidad
    if (!e.id || !/^BRF-\d{4}$/.test(String(e.id))) falla('identificador', idE, 'el identificador falta o no tiene la forma BRF-0000')
    else if (ids[e.id]) falla('identificador', idE, 'el identificador está repetido (también en la posición ' + ids[e.id] + ')')
    else ids[e.id] = i + 1

    // ── campos completos
    for (var c = 0; c < CAMPOS_OBLIGATORIOS.length; c++) {
      var k = CAMPOS_OBLIGATORIOS[c]
      var v = e[k]
      if (v === undefined || v === null || (typeof v === 'string' && !v.trim())) falla('campo_faltante', idE, 'falta el campo «' + k + '» (si no se sabe, se declara como hueco · no se deja vacío)')
    }
    for (var d = 0; d < CAMPOS_LISTA.length; d++) {
      if (!Array.isArray(e[CAMPOS_LISTA[d]])) falla('campo_faltante', idE, 'el campo «' + CAMPOS_LISTA[d] + '» debe ser una lista (aunque esté vacía)')
    }

    // ── R1 · un solo mensaje
    var msg = e.mensaje
    if (msg !== undefined && msg !== null) {
      if (typeof msg !== 'string') falla('un_mensaje', idE, 'el mensaje no es UN texto (es ' + (Array.isArray(msg) ? 'una lista' : typeof msg) + ') · un brief = un mensaje')
      else {
        var frases = msg.split(/[.!?¡¿]+/).map(function (s) { return s.trim() }).filter(Boolean)
        if (frases.length > 2) falla('un_mensaje', idE, 'el mensaje tiene ' + frases.length + ' frases · sospecha de varios mensajes (máximo 2 frases, una idea)')
        if (msg.length > 260) falla('un_mensaje', idE, 'el mensaje mide ' + msg.length + ' caracteres · una idea cabe en 260')
      }
    }

    // ── R3 · el público no es «todos»
    var seg = normalizar(e.segmento)
    if (seg) {
      var cliches = ['todos', 'todo el mundo', 'toda la poblacion', 'publico general', 'cualquier persona', 'cualquiera', 'toda la gente', 'la gente']
      for (var q = 0; q < cliches.length; q++) {
        if (seg === cliches[q] || seg.indexOf(cliches[q] + ' ') === 0 || (seg.length < 40 && seg.indexOf(cliches[q]) !== -1)) {
          falla('publico_no_es_todos', idE, 'el segmento dice «' + e.segmento + '» · no es una audiencia declarada')
          break
        }
      }
      if (seg.length < 25) falla('publico_no_es_todos', idE, 'el segmento es demasiado corto (' + seg.length + ' caracteres) para ser una audiencia declarada')
    }

    // ── nada de videos con brief (el sistema no mira video)
    var tipo = normalizar(e.tipo_de_pieza)
    if (TIPOS_QUE_NO_SE_BRIEFEAN.indexOf(tipo) !== -1) falla('video_sin_pendiente', idE, 'es una pieza de «' + e.tipo_de_pieza + '» y trae brief · el sistema mira imágenes, no video ni audio · debía ir a «pendientes_declarados»')
    else if (tipo && TIPOS_SIN_VIDEO.indexOf(tipo) === -1 && TIPOS_QUE_NO_SE_BRIEFEAN.indexOf(tipo) === -1) falla('tipo_desconocido', idE, 'tipo_de_pieza «' + e.tipo_de_pieza + '» no está entre ' + TIPOS_SIN_VIDEO.join('/'))

    // ── R6 · toda regla visual trae su muestra
    var vis = e.visual
    if (vis && typeof vis === 'object' && !Array.isArray(vis)) {
      if (!vis.muestra || !String(vis.muestra).trim()) falla('visual_sin_muestra', idE, 'la regla visual no declara su muestra (cuántas piezas se miraron y qué no se pudo observar) · R6')
    } else if (typeof vis === 'string' && vis.trim() && normalizar(vis) !== 'n a' && normalizar(vis) !== 'no aplica') {
      falla('visual_sin_muestra', idE, 'el visual es solo texto sin muestra declarada · debe ser un objeto {capa_que_manda, descripcion, muestra} · R6')
    } else if (!vis) falla('campo_faltante', idE, 'falta el campo «visual» (si no aplica, se declara «no aplica»)')

    // ── procedencia: cada brief cita su parte del plan y la cita existe
    var cita = String(e.de_que_parte_del_plan || '')
    if (cita.trim()) {
      var citaNorm = normalizar(cita)
      var hayMarca = /§|seccion|semana|fase|paso|puerta|camino|ciclo|mes\s*\d/.test(citaNorm) || citaNorm.length >= 12
      var enPlan = citaNorm.length >= 12 && planNorm.indexOf(citaNorm) !== -1
      var comillas = cita.match(/[«"“]([^»"”]{12,})[»"”]/)
      var textoCitado = comillas ? normalizar(comillas[1]) : ''
      var citaVerificada = enPlan || (textoCitado && planNorm.indexOf(textoCitado) !== -1)
      if (!hayMarca) falla('cita_al_plan', idE, 'la cita al plan es demasiado vaga: «' + cita + '»')
      else if (planNorm && !citaVerificada && !/§/.test(cita)) falla('cita_al_plan', idE, 'la cita «' + cita.slice(0, 80) + '» no se encuentra en el plan · no se puede verificar la procedencia')
    }

    // ── centinelas: cifras que terminan en ,77 / .77 = copió el documento de referencia
    var todoElBrief = aTexto(e)
    var m77 = todoElBrief.match(CENTINELA)
    if (m77) falla('centinela', idE, 'aparece la cifra «' + m77[0] + '» (termina en ,77) · copió el ejemplo de la referencia en vez de pensar')

    // ── palabras prohibidas del manual, en lo que el brief PIDE (no en las listas de lo prohibido)
    var pedido = aTexto([e.que_es, e.objetivo, e.segmento, e.protagonista, e.mensaje, e.hipotesis, e.limites, e.sintaxis, e.llamado_a_la_accion, e.variantes, e.visual, e.vocabulario_obligatorio])
    var pedNorm = normalizar(pedido)
    for (var w = 0; w < prohibidas.length; w++) {
      if (palabraPresente(pedNorm, prohibidas[w])) falla('palabra_prohibida', idE, 'usa «' + prohibidas[w] + '», prohibida por el manual (búsqueda literal)')
    }

    // ── para el chequeo de repetidos
    var clave = normalizar(e.mensaje)
    if (clave) (mensajes[clave] = mensajes[clave] || []).push(idE)
  }

  // ── ningún brief repetido: dos con el mismo mensaje, uno sobra
  Object.keys(mensajes).forEach(function (m) {
    if (mensajes[m].length > 1) falla('brief_repetido', mensajes[m].join(' · '), 'comparten el mismo mensaje · «un brief = una estrategia»: uno sobra')
  })

  // ── centinelas también en lo que declara fuera de los briefs
  var fuera = aTexto([parte && parte.huecos, parte && parte.contradicciones_plan_vs_manual, parte && parte.pendientes_declarados])
  var f77 = fuera.match(CENTINELA)
  if (f77) falla('centinela', null, 'aparece la cifra «' + f77[0] + '» en los huecos/contradicciones/pendientes')

  var por = {}
  hallazgos.forEach(function (h) { por[h.chequeo] = (por[h.chequeo] || 0) + 1 })
  return { ok: hallazgos.length === 0, hallazgos: hallazgos, por_chequeo: por, entregables_revisados: ents.length }
}


// ④ CHEQUEOS · cuerpo del nodo · CC#1 · 2026-09-29 (la lógica pura `brief-chequeos.js` va ANTEPUESTA por el constructor).
// Gratis y en código. Lo que falle SE DECLARA en el parte · NO se corrige solo. Arma la fila que ⑤ guardará y el aviso de ⑥.
const c = $input.first().json
const ext = c.llego_la_vuelta ? extraerParte(c.texto) : { legible: false, motivo: c.motivo || 'la vuelta del redactor no llegó' }
const manual = { forbidden_words: c.forbidden_words || [], required_terminology: c.required_terminology || [] }
const parte = ext.legible ? ext.parte : { entregables: [], pendientes_declarados: [], huecos: [], contradicciones_plan_vs_manual: [] }
const res = ext.legible
  ? chequear(parte, manual, c.plan_texto)
  : { ok: false, hallazgos: [{ chequeo: 'respuesta_no_legible', entregable: null, detalle: ext.motivo }], por_chequeo: { respuesta_no_legible: 1 }, entregables_revisados: 0 }

// ── 03-oct · EL TRATO: el texto que cada brief propone al público respeta el trato de la marca (candidato · no fatal · se DECLARA)
if (ext.legible && c.trato && typeof chequearTrato === 'function') {
  parte.entregables.forEach((e) => {
    const texto = [e && e.mensaje, e && e.llamado_a_la_accion, e && e.variantes, e && e.sintaxis].filter(Boolean).join(' . ')
    chequearTrato(c.trato, texto, 'el brief ' + (e && e.id)).forEach((h) => { res.hallazgos.push({ chequeo: 'brief_en_otro_trato', entregable: e && e.id, detalle: h.detalle }); res.por_chequeo.brief_en_otro_trato = (res.por_chequeo.brief_en_otro_trato || 0) + 1; res.ok = false })
  })
}

// ── EL VEREDICTO · un parte que no vale NO se lee como éxito (encargo Lenovo 30-sep §2) ──────────────────────
// Inválido = la vuelta no llegó · la respuesta no se pudo leer como parte · trae 0 entregables · o falla un chequeo de CONTEO/CIFRAS
// (sin_entregables · centinela: la cifra copiada del ejemplo). Los demás hallazgos siguen SOLO declarándose (no se corrigen solos).
// Nada se rellena: un parte vacío se llama vacío.
const CHEQUEOS_FATALES = ['respuesta_no_legible', 'sin_entregables', 'centinela']
const motivos = []
if (!c.llego_la_vuelta) motivos.push(c.falla_del_redactor ? 'el redactor FALLÓ · ' + c.falla_del_redactor : 'la vuelta del redactor NO llegó')
if (!ext.legible) motivos.push('la respuesta no se pudo leer como parte (' + (ext.motivo || 'sin motivo') + ')')
if (ext.legible && parte.entregables.length === 0) motivos.push('entregables: 0')
res.hallazgos.filter((h) => CHEQUEOS_FATALES.indexOf(h.chequeo) !== -1 && h.chequeo !== 'respuesta_no_legible' && h.chequeo !== 'sin_entregables').forEach((h) => motivos.push('falla el chequeo «' + h.chequeo + '»' + (h.entregable ? ' en ' + h.entregable : '')))
const parte_valido = motivos.length === 0
const motivo_invalido = parte_valido ? null : motivos.join(' · ')

// ── el parte, legible (lo que Emilio lee en Drive) ────────────────────────────────────────────────
const L = []
const p = (s) => L.push(s === undefined ? '' : s)
const lista = (a) => (Array.isArray(a) && a.length ? a.map((x) => '  - ' + (typeof x === 'string' ? x : JSON.stringify(x))).join('\n') : '  (ninguno)')
const hoy = new Date().toISOString().slice(0, 10)
if (!parte_valido) {
  p('# ⛔ PARTE NO VÁLIDO · NO USAR')
  p('Motivo: ' + motivo_invalido)
  p('Este documento se conserva sólo para diagnóstico. No es un parte de trabajo.')
  p('')
}
p('# PARTE DE TRABAJO · ' + c.client_name + ' · ' + hoy)
p('Plan de origen: ' + c.plan_id + ' · Manual: versión ' + c.manual_version + ' (' + c.manual_id + ')' + (c.dry_run ? ' · ⚠️ MODO SECO (no es un parte real)' : ''))
p('')
if (ext.reparado) p('> ⚠️ Formato reparado: el redactor escribió ' + ext.comillas_reparadas + ' comilla(s) doble(s) sin escapar dentro de un texto y se escaparon para poder leer el parte · el CONTENIDO no se alteró.')
p('## Estado de los chequeos: ' + (res.ok ? '✅ sin hallazgos' : '⚠️ ' + res.hallazgos.length + ' hallazgo(s) DECLARADOS · no se corrigieron solos'))
if (!res.ok) {
  Object.keys(res.por_chequeo).forEach((k) => p('- ' + k + ': ' + res.por_chequeo[k]))
  p('')
  res.hallazgos.forEach((h) => p('- [' + h.chequeo + ']' + (h.entregable ? ' ' + h.entregable + ' ·' : '') + ' ' + h.detalle))
}
p('')
if (c.plan_del_sobre_distinto) p('> ⚠️ El sobre nombraba el plan ' + c.plan_del_sobre + ' pero el plan vigente es ' + c.plan_id + ' · se usó el vigente.')
p('## Entregables (' + parte.entregables.length + ')')
parte.entregables.forEach((e) => {
  p('')
  p('### ' + (e.id || '(sin id)') + ' · ' + (e.plataforma || '?') + ' · ' + (e.tipo_de_pieza || '?'))
  p('- QUÉ ES: ' + (e.que_es || ''))
  p('- DE QUÉ PARTE DEL PLAN SALE: ' + (e.de_que_parte_del_plan || ''))
  p('- OBJETIVO: ' + (e.objetivo || ''))
  p('- SEGMENTO: ' + (e.segmento || ''))
  p('- PROTAGONISTA: ' + (e.protagonista || ''))
  p('- MENSAJE (uno): ' + (typeof e.mensaje === 'string' ? e.mensaje : JSON.stringify(e.mensaje)))
  p('- HIPÓTESIS: ' + (e.hipotesis || ''))
  p('- LÍMITES: ' + (e.limites || ''))
  p('- VOCABULARIO OBLIGATORIO:\n' + lista(e.vocabulario_obligatorio))
  p('- PROHIBIDO:\n' + lista(e.prohibido))
  p('- SINTAXIS: ' + (e.sintaxis || ''))
  const v = e.visual
  p('- VISUAL: ' + (v && typeof v === 'object' ? 'capa que manda: ' + (v.capa_que_manda || '?') + ' · ' + (v.descripcion || '') + ' · MUESTRA: ' + (v.muestra || '(sin muestra)') : String(v || '')))
  p('- LLAMADO A LA ACCIÓN: ' + (e.llamado_a_la_accion || ''))
  p('- VARIANTES: ' + (e.variantes || ''))
  p('- NEGATIVOS:\n' + lista(e.negativos))
  p('- APRUEBA Y PARA CUÁNDO: ' + (e.aprueba_y_para_cuando || ''))
  p('- PRESUPUESTO: ' + (e.presupuesto === null || e.presupuesto === undefined ? '(no fijado por el plan)' : String(e.presupuesto)))
})
p('')
p('## Pendientes DECLARADOS (no se pueden briefear todavía)')
;(parte.pendientes_declarados || []).forEach((x) => p('- ' + (x.entregable || '?') + (x.plataforma ? ' · ' + x.plataforma : '') + ' — ' + (x.motivo || '')))
if (!(parte.pendientes_declarados || []).length) p('(ninguno declarado)')
p('')
p('## Huecos declarados (lo que faltaba y NO se rellenó)')
p(lista(parte.huecos))
p('')
p('## Contradicciones plan ↔ manual (declaradas, no obedecidas)')
;(parte.contradicciones_plan_vs_manual || []).forEach((x) => p('- ' + (x.que || '?') + ' · el plan dice: ' + (x.plan_dice || '?') + ' · el manual dice: ' + (x.manual_dice || '?') + ' · ' + (x.que_se_hizo || '')))
if (!(parte.contradicciones_plan_vs_manual || []).length) p('(ninguna declarada)')
p('')
p('## Dependencias')
p(lista(parte.dependencias))
if (!ext.legible) {
  p('')
  p('## ⚠️ Respuesta del redactor (no legible como parte · se guarda tal cual para diagnóstico)')
  p(String(c.texto || '').slice(0, 6000))
}
const parte_md = L.join('\n')

const fila_parte = {
  client_id: c.client_id,
  title: (parte_valido ? '' : '⛔ PARTE NO VÁLIDO · ') + 'Parte de trabajo · briefs · ' + hoy,
  output_type: 'campaign_brief_pack',
  content: parte_md,
  content_text: parte_md,
  producing_agent: 'campaign-brief-agent',
  status: 'draft',
  provenance_tag: {
    fuente: 'brief',
    workflow_id: $workflow.id,
    workflow_execution_id: $execution.id,
    plan_id: c.plan_id,
    manual_id: c.manual_id,
    manual_version: c.manual_version,
    legible: ext.legible,
    reparado: ext.reparado === true,
    comillas_reparadas: ext.comillas_reparadas || 0,
    valido: parte_valido,
    motivo_invalido,
    chequeos_ok: res.ok,
    hallazgos: res.hallazgos.length,
    por_chequeo: res.por_chequeo,
    entregables: parte.entregables.length,
    pendientes: (parte.pendientes_declarados || []).length,
    huecos: (parte.huecos || []).length,
    dry_run: c.dry_run === true,
    guardado_antes_de_drive: true,
    tope_usd: c.tope_usd === undefined ? null : c.tope_usd,
    costo_usd: c.vuelta_costo_usd === undefined ? null : c.vuelta_costo_usd,
    parte: ext.legible ? parte : null,
  },
}
const payload_cable = {
  event_type: 'run_completed',
  worker_id: $workflow.id,
  worker_name: 'brief',
  // el cable declara el resultado REAL (el cierre ⑤ lo corrige a parte_no_valido / parte_con_problemas si algo falla)
  resultado: parte_valido ? 'parte_terminado' : 'parte_no_valido',
  ...(parte_valido ? {} : { motivo: motivo_invalido }),
  client_id: c.client_id,
  tenant_id: c.tenant_id || c.client_id,
  _sala_correlation_id: c._sala_correlation_id || null,
  _journey_id: c._journey_id || null,
  ts: new Date().toISOString(),
}
return [{
  json: {
    client_id: c.client_id,
    client_name: c.client_name,
    dry_run: c.dry_run === true,
    plan_id: c.plan_id,
    manual_id: c.manual_id,
    cuerpo_dry_run_enviado: c.cuerpo && c.cuerpo.dry_run,
    llego_la_vuelta: c.llego_la_vuelta,
    vuelta_real: c.vuelta_real,
    simulacro_usado: c.simulacro_usado,
    vuelta_costo_usd: c.vuelta_costo_usd,
    vuelta_modelo: c.vuelta_modelo,
    falla_del_redactor: c.falla_del_redactor || null,
    tope_usd: c.tope_usd === undefined ? null : c.tope_usd,
    parte_legible: ext.legible,
    parte_reparado: ext.reparado === true,
    comillas_reparadas: ext.comillas_reparadas || 0,
    parte_valido,
    motivo_invalido,
    titulo_parte: fila_parte.title,
    chequeos_ok: res.ok,
    hallazgos: res.hallazgos,
    por_chequeo: res.por_chequeo,
    entregables: parte.entregables.length,
    pendientes_declarados: (parte.pendientes_declarados || []).length,
    _sala_correlation_id: c._sala_correlation_id || null,
    _journey_id: c._journey_id || null,
    parte_md,
    fila_parte,
    payload_cable,
  },
}]

// ⑤ SECO · LO QUE SE HABRÍA ESCRITO · CC#1 · 2026-09-29. En modo seco NADA se escribe ni se avisa: ni la tabla, ni Drive, ni la sala.
// Pero llega hasta acá con las MISMAS filas y avisos que el camino real (los arma ④), y aquí se VALIDAN sus formas.
const c = $input.first().json
const f = c.fila_parte || {}
const faltan = []
for (const k of ['client_id', 'title', 'output_type', 'content', 'content_text', 'producing_agent', 'status', 'provenance_tag']) {
  if (f[k] === undefined || f[k] === null || f[k] === '') faltan.push('fila_parte.' + k)
}
if (f.output_type !== 'campaign_brief_pack') faltan.push('fila_parte.output_type debe ser campaign_brief_pack')
if (f.status !== 'draft') faltan.push('fila_parte.status debe ser draft')
const a = c.payload_cable || {}
for (const k of ['event_type', 'worker_id', 'worker_name', 'resultado', 'client_id']) {
  if (a[k] === undefined || a[k] === null || a[k] === '') faltan.push('payload_cable.' + k)
}
if (a.event_type !== 'run_completed') faltan.push('payload_cable.event_type debe ser run_completed')
if (a.worker_name !== 'brief') faltan.push('payload_cable.worker_name debe ser brief')
const habria_cerrado_como = c.parte_valido === false ? 'ERROR · PARTE_NO_VALIDO · ' + c.motivo_invalido : 'parte_terminado'
const salida = {
  json: {
    seco: true,
    escrituras_reales: 0,
    no_se_escribio_en: ['client_historical_outputs', 'Drive (texto-a-drive)', 'la sala (SALA_CALLBACK_URL)'],
    dry_run_enviado_al_nodo_que_paga: c.cuerpo_dry_run_enviado,
    la_vuelta_del_redactor: { llego: c.llego_la_vuelta, real: c.vuelta_real, simulacro: c.simulacro_usado, costo_usd: c.vuelta_costo_usd, modelo: c.vuelta_modelo },
    chequeos: { legible: c.parte_legible, ok: c.chequeos_ok, por_chequeo: c.por_chequeo, entregables: c.entregables, pendientes: c.pendientes_declarados },
    habria_guardado: { tabla: 'client_historical_outputs', output_type: f.output_type, status: f.status, titulo: f.title, largo_del_parte: String(f.content || '').length, provenance_tag_claves: Object.keys(f.provenance_tag || {}) },
    habria_subido_a_drive_con_titulo: f.title,
    parte_valido: c.parte_valido !== false,
    motivo_invalido: c.motivo_invalido || null,
    habria_cerrado_como,
    habria_avisado: a,
    formas_validas: faltan.length === 0,
    faltan,
  },
}
// 🔴 el ensayo ejerce el MISMO veredicto que el camino real: un parte inválido termina la corrida en error (con la salida ya guardada en la ejecución)
if (c.parte_valido === false) throw new Error('PARTE_NO_VALIDO (modo seco) · ' + c.motivo_invalido + ' · en modo real habría subido a Drive con la marca y cerrado en error')
return [salida]

// ⑤ ¿GUARDÓ Y SALIÓ EL PDF? · CC#1 · 2026-09-29. Una corrida sin parte guardado o sin PDF NO puede salir exitosa (regla 12-sep de planeación).
// El guardado va ANTES de Drive a propósito: si Drive falla, el parte NO se pierde.
const v = $('④ Chequeos').first().json
let guardado = false, guardado_id = null
try {
  const g = $('⑤ Guardar el parte').first().json
  const gb = g && g.body ? g.body : g
  const fila = Array.isArray(gb) ? gb[0] : gb
  guardado = !!(fila && fila.id)
  guardado_id = (fila && fila.id) || null
} catch (x) { guardado = false }
let rec = null
try { const d = $('⑤ Parte a Drive').first().json; rec = d && d.body ? d.body : d } catch (x) { rec = null }
const hayPdf = !!(rec && rec.ok === true && rec.file_id)
const problemas = []
if (v.parte_valido === false) problemas.push('PARTE NO VÁLIDO · ' + v.motivo_invalido)
if (!v.llego_la_vuelta) problemas.push('la vuelta del redactor NO llegó')
if (!guardado) problemas.push('el parte NO quedó guardado en client_historical_outputs')
if (!hayPdf) problemas.push('Drive no devolvió un archivo (' + String((rec && rec.motivo) || 'sin motivo') + ')')
return [{
  json: {
    ok: problemas.length === 0,
    parte_guardado: guardado,
    parte_guardado_id: guardado_id,
    hay_pdf: hayPdf,
    file_id: (rec && rec.file_id) || null,
    url: (rec && rec.url) || null,
    chequeos_ok: v.chequeos_ok,
    hallazgos: (v.hallazgos || []).length,
    entregables: v.entregables,
    pendientes_declarados: v.pendientes_declarados,
    problemas,
    parte_valido: v.parte_valido !== false,
    motivo_invalido: v.motivo_invalido || null,
    client_id: v.client_id,
    // la sala se entera del resultado REAL: un parte con problemas no se anuncia como terminado limpio
    payload_cable: { ...v.payload_cable, resultado: problemas.length === 0 ? 'parte_terminado' : (v.parte_valido === false ? 'parte_no_valido' : 'parte_con_problemas'), ...(problemas.length ? { problemas } : {}) },
  },
}]

// ⑥ EL CABLE DE VUELTA NO PUEDE SER MUDO · CC#1 · 2026-09-29 · igual que planeación.
// Si no volvió, la sala NUNCA se entera de que la corrida terminó y su marca queda sin resolver.
const r = $input.first().json || {}
const volvio = r.ok === true
let corr = null
try { corr = $('⓪ Sobre · llave · modo seco').first().json._sala_correlation_id || null } catch (e) { corr = null }
// Falla RUIDOSA solo si la sala lo despachó: un disparo a mano no tiene a quién contestarle.
if (corr && !volvio) {
  throw new Error('CABLE_DE_VUELTA_MUDO · la sala NO se enteró de que la corrida terminó · código ' + String(r.code || r.error || 'sin código'))
}
// 🔴 LA CORRIDA NO CIERRA «CORRECTA» SI EL PARTE NO VALE (encargo Lenovo 30-sep §2): el cable YA declaró el resultado real arriba;
// acá la corrida termina en ERROR visible con el motivo, no en verde. Antes este nodo devolvía siempre `cierre: 'parte_terminado'`.
let cierrePrevio = null
try { cierrePrevio = $('⑤ ¿Guardó y salió el PDF?').first().json } catch (e) { cierrePrevio = null }
if (cierrePrevio && cierrePrevio.ok === false) {
  throw new Error((cierrePrevio.parte_valido === false ? 'PARTE_NO_VALIDO' : 'PARTE_CON_PROBLEMAS') + ' · ' + (cierrePrevio.problemas || []).join(' | ') + ' · la sala ya fue avisada del resultado real')
}
return [{
  json: {
    cierre: 'parte_terminado',
    vuelta_ok: volvio,
    vuelta_detalle: volvio ? r.event_id || 'sin event_id' : r.code || r.detail || r.error || 'sin respuesta de la sala',
    despachado_por_la_sala: !!corr,
  },
}]
